<?php declare(strict_types=1); require __DIR__.'/_bootstrap.php';require_admin();if(!is_post())redirect_to('products.php');verify_csrf($_POST['csrf']??'');$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($id){$s=$pdo->prepare('SELECT image_path FROM products WHERE id=?');$s->execute([$id]);$p=$s->fetch();$pdo->prepare('DELETE FROM products WHERE id=?')->execute([$id]);if($p)delete_upload($p['image_path']??null);flash('success','Fabric deleted.');}redirect_to('products.php');
